/* Grid - 2D layout */
.container {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: auto auto;
}

/* Flexbox - 1D layout */
.navbar {
  display: flex;
  justify-content: space-between;
}

.container {
  display: grid;
  grid-template-columns: 100px 200px 1fr; /* 3 columns */
  grid-template-rows: 80px auto 60px;     /* 3 rows */
}

.container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;          /* same gap for rows and columns */
  /* OR */
  row-gap: 10px;
  column-gap: 20px;
}

.container {
  display: grid;
  grid-template-columns: 1fr 2fr 1fr; /* space divided in ratio 1:2:1 */
}

/* vs percentage, which needs manual calculation with gaps */
.container2 {
  display: grid;
  grid-template-columns: 25% 50% 25%;
}

.container {
  display: grid;
  grid-template-columns: 1fr 3fr;
  grid-template-rows: auto 1fr auto;
  grid-template-areas:
    "header header"
    "sidebar content"
    "footer footer";
}

.header  { grid-area: header; }
.sidebar { grid-area: sidebar; }
.content { grid-area: content; }
.footer  { grid-area: footer; }

.container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}
/* Columns automatically increase or decrease based on screen width */

.container {
  display: grid;
  grid-template-columns: repeat(3, 1fr); /* explicit: 3 columns */
  grid-auto-rows: 100px; /* implicit rows created automatically get this height */
}
